MATCH (s:PlantItem {tag: "TK-3-3"}), (t:PlantItem {tag: "T-47-4"})
RETURN s.tag AS from_tag, t.tag AS to_tag,
       EXISTS { MATCH (s)-[:send_to*1..]->(t) } AS flow_path_exists;

MATCH (source:PlantItem {tag: "TK-3-3"}), (target:PlantItem {tag: "T-47-4"})
OPTIONAL MATCH path = (source)-[:send_to*1..]->(target)
RETURN source.tag AS source_tag, target.tag AS target_tag, path IS NOT NULL AS reachable;

MATCH (start:PlantItem {tag: "P-32-1"}), (target:PlantItem {tag: "E-35-1"})
OPTIONAL MATCH p = (start)-[:send_to*1..]->(target)
RETURN start.tag AS from_tag, target.tag AS to_tag, p IS NOT NULL AS can_process_flow_reach_to_target;

MATCH (source:PlantItem {tag: "P-32-1"}), (target:PlantItem {tag: "E-35-1"})
OPTIONAL MATCH path = (source)-[:send_to*1..]->(target)
RETURN source.tag AS source_tag, target.tag AS target_tag, path IS NOT NULL AS reachable;

MATCH (hx:HeatExchanger)
WHERE hx.unit_id = "47"
RETURN count(hx) AS count, collect(hx.tag) AS tags;

MATCH (hx:PlantItem:HeatExchanger)
WHERE toString(hx.unit_id) = '47'
RETURN count(hx) AS hx_count;

MATCH (h:HeatExchanger)
WHERE h.unit_id = '47'
RETURN count(h) AS count, collect(h.tag) AS tags }

MATCH (v:PlantItem:PressureVessel)
WHERE v.unit_id = "36"
RETURN count(v.tag) AS number_of_pressure_vessels NEITHER;

MATCH (v:PressureVessel:PlantItem)
WHERE v.unit_id = '36'
RETURN count(v) AS count, collect(v.tag) AS tags;

MATCH (equipment:Equipment {tag: 'E-30-3'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (tank:Tank {tag: "T-16-3"})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: "CHV-21-4"})-[:is_located_in]->(section:PlantSection)
RETURN item.tag AS tag, section.unit_id AS unit_id
}

MATCH (item:PlantItem {tag: "P-23-1"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "P-23-1"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "P-23-1"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "P-23-1"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS drawing_sheet
ORDER BY drawing_sheet;

MATCH (item:PlantItem {tag: "T-32-2"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH path = shortestPath(
  (start:PlantItem {tag: 'V-13-7'})-[:send_to*]->(finish:PlantItem {tag: 'GV-12-10'})
)
RETURN [item IN nodes(path)
        WHERE item:Equipment OR item:OperatedValve OR item:BallValve OR item:GlobeValve OR item:CheckValve
        | item.tag] AS equipment_and_valves_in_order;

MATCH p = (upstream:Equipment)-[:send_to*1..]->(tank:PlantItem {tag: "T-13-5"})
UNWIND nodes(p) AS item
WITH DISTINCT item
WHERE (item:BallValve OR item:GlobeValve)
  AND NOT EXISTS {
    MATCH (:ActuatingFunction)-[:control]->(item)
  }
RETURN item.tag AS tag
ORDER BY tag
LIMIT 1000;

